function sequencePreview(manifest) {
  const units = manifest.units.slice();
  const indegree = new Map();
  const outgoing = new Map();

  for (const name of units) {
    indegree.set(name, 0);
    outgoing.set(name, new Set());
  }

  for (const link of manifest.links) {
    const neighbors = outgoing.get(link.before);
    if (!neighbors.has(link.after)) {
      neighbors.add(link.after);
      indegree.set(link.after, indegree.get(link.after) + 1);
    }
  }

  const available = units.filter(name => indegree.get(name) === 0);
  const order = [];

  while (available.length > 0) {
    let bestIndex = 0;

    for (let i = 1; i < available.length; i++) {
      if (available[i] < available[bestIndex]) {
        bestIndex = i;
      }
    }

    const current = available.splice(bestIndex, 1)[0];
    order.push(current);

    for (const next of outgoing.get(current)) {
      const nextIndegree = indegree.get(next) - 1;
      indegree.set(next, nextIndegree);

      if (nextIndegree === 0) {
        available.push(next);
      }
    }
  }

  return order.length === units.length ? { order } : null;
}
